verification_commands.ac1:
set -u
F=docs/criteria/scoring_map/app.md
test -f "$F" || { echo "ac1 RED: $F missing - this card's whole deliverable is this file"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Application[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac1 RED: no '## Application' section - the rubric grades a full-stack end-to-end app that runs locally with a single command"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac1 RED: no '- Claim: N/M' line in the exact record format"; exit 1; }
set -- $CL
[ "$1" -le "$2" ] && [ "$2" = "2" ] || { echo "ac1 RED: the Application claim '$1/$2' is malformed or does not use the rubric maximum 2"; exit 1; }
printf "%s\n" "$S" | grep -qE "^- Reason: ..*" || { echo "ac1 RED: no measured Reason line"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac1 RED: no single backticked First entry point"; exit 1; }
[ "$(printf "%s\n" "$S" | grep -cE '^- First entry point:')" = "1" ] || { echo "ac1 RED: more than one First entry point line"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac1 RED: first entry point '$EP' does not exist on this tree"; exit 1; } ;; esac
printf "%s\n" "$S" | grep -qE 'npm run dev' || { echo "ac1 RED: the record never names npm run dev - that is the single command the rubric's 'runs locally with a single command' clause is about"; exit 1; }
printf "%s\n" "$S" | grep -qE 'package[.]json' || { echo "ac1 RED: the record never names package.json - the single-command surface is a file a grader can open in 30 seconds"; exit 1; }
printf "%s\n" "$S" | grep -qiE "Quick Start" || { echo "ac1 RED: the record does not point at README ## Quick Start - the documented run path is where a grader looks first"; exit 1; }
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac1 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac1 GREEN: APPLICATION recorded - claim $1/$2, one existing first entry point ($EP), the single-command surface (npm run dev + package.json + Quick Start) named, every evidence path resolves"

verification_commands.ac2:
set -u
F=docs/criteria/scoring_map/app.md
test -f "$F" || { echo "ac2 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Testing[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac2 RED: no '## Testing' section - the rubric requires unit AND integration tests behind a single command"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac2 RED: no '- Claim: N/M' line"; exit 1; }
set -- $CL
[ "$1" -le "$2" ] && [ "$2" = "2" ] || { echo "ac2 RED: the Testing claim '$1/$2' is malformed or does not use the rubric maximum 2"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac2 RED: no single backticked First entry point"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac2 RED: first entry point '$EP' does not exist"; exit 1; } ;; esac
printf "%s\n" "$S" | grep -qE 'backend/tests/unit' || { echo "ac2 RED: the record never names backend/tests/unit - the unit tier must be locatable"; exit 1; }
printf "%s\n" "$S" | grep -qE 'backend/tests/integration' || { echo "ac2 RED: the record never names backend/tests/integration - the integration tier is half the rubric clause and it is the tier most projects fake"; exit 1; }
printf "%s\n" "$S" | grep -qiE "vitest|frontend" || { echo "ac2 RED: the record says nothing about the frontend test tier - the app is full-stack and so is its test surface"; exit 1; }
printf "%s\n" "$S" | grep -qiE "uv run pytest|npm run test|make test|npm test" || { echo "ac2 RED: the record names no single-command runner - 'run with a single command and pass' is the rubric clause"; exit 1; }
printf "%s\n" "$S" | grep -qE 'ci[.]yml' || { echo "ac2 RED: the record never names .github/workflows/ci.yml - the CI evidence is what makes 'pass' attestable outside this machine"; exit 1; }
# both tiers must really exist, and a stated test count must be re-measurable
test -d backend/tests/unit || { echo "ac2 RED: backend/tests/unit does not exist - the record points at a tier that is not there"; exit 1; }
test -d backend/tests/integration || { echo "ac2 RED: backend/tests/integration does not exist"; exit 1; }
UT=$(ls backend/tests/unit/test_*.py 2>/dev/null | wc -l | tr -d " ")
IT=$(ls backend/tests/integration/test_*.py 2>/dev/null | wc -l | tr -d " ")
echo "ac2 evidence: re-measurable tier sizes unit_files=$UT integration_files=$IT"
[ "${UT:-0}" -ge 1 ] && [ "${IT:-0}" -ge 1 ] || { echo "ac2 RED: unit_files=$UT integration_files=$IT - one tier is empty, so a 2/2 claim would be false and the record must claim less"; exit 1; }
N=$(printf "%s\n" "$S" | sed -n 's/.*at least \([0-9][0-9]*\) backend test files.*/\1/p' | head -1)
if [ -n "$N" ]; then
  TOT=$((UT + IT))
  printf "%s\n" "$S" | grep -qiE '2026-[0-9]{2}-[0-9]{2}' || { echo "ac2 RED: the record states a test-file count without a 2026-mm-dd measurement date - test tiers grow as later cards land, so an undated count is a claim with an expiry date nobody wrote down"; exit 1; }
  [ "$N" -le "$TOT" ] || { echo "ac2 RED: the record's floor is at least $N backend test files but the tree measures $TOT (unit=$UT integration=$IT) - a floor above the measurement is an invented number, and a number no fence can re-measure is exactly the defect class this milestone exists to remove"; exit 1; }
  echo "ac2 evidence: the stated floor (at least $N backend test files, date-stamped) is at or below the measured $TOT, so the floor holds as the tiers grow"
else
  echo "ac2 evidence: the record states no backend test-file count - allowed, because the rubric clause is unit AND integration behind one command, not a number; the tiers are measured here anyway: unit=$UT integration=$IT"
fi
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac2 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac2 GREEN: TESTING recorded - claim $1/$2, both tiers locatable and non-empty (unit=$UT integration=$IT), a single-command runner named, CI named, and any stated count re-measurable"

verification_commands.ac3:
set -u
F=docs/criteria/scoring_map/app.md
test -f "$F" || { echo "ac3 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Containerization[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac3 RED: no '## Containerization' section - the rubric requires the full system including the database via Docker/Compose with a single command"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac3 RED: no '- Claim: N/M' line"; exit 1; }
set -- $CL
[ "$1" -le "$2" ] && [ "$2" = "2" ] || { echo "ac3 RED: the Containerization claim '$1/$2' is malformed or does not use the rubric maximum 2"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac3 RED: no single backticked First entry point"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac3 RED: first entry point '$EP' does not exist"; exit 1; } ;; esac
test -f Dockerfile || { echo "ac3 RED: Dockerfile is gone from the tree - the claim it supports cannot be true"; exit 1; }
test -f docker-compose.yml || { echo "ac3 RED: docker-compose.yml is gone from the tree"; exit 1; }
printf "%s\n" "$S" | grep -qE 'Dockerfile' || { echo "ac3 RED: the record never names Dockerfile"; exit 1; }
printf "%s\n" "$S" | grep -qE 'docker-compose[.]yml|docker compose' || { echo "ac3 RED: the record never names the compose surface"; exit 1; }
printf "%s\n" "$S" | grep -qiE "database|sqlite|db" || { echo "ac3 RED: the record says nothing about the database being containerized - 'full system incl. database' is the rubric clause"; exit 1; }
# --- MEASURE the database clause rather than trusting the prose: the compose file must
# really carry a database SERVICE with a real database image, or the 2/2 claim is an
# assumption. (Measured at groom: docker-compose.yml declares exactly two services, db
# on postgres:16-alpine with a healthcheck and a named volume, and app gated on
# service_healthy. If that ever stops being true, this fence forces the honest
# sub-claim instead of letting the record keep a false 'full system incl. database'.)
DBSVC=$(python3 - <<'PYDB'
import re
txt = open("docker-compose.yml", encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
msvc = re.search(r"^services:[ \t]*$", txt, re.M)
if not msvc:
    print("none|False|False")
    raise SystemExit(0)
body = txt[msvc.end():]
services = re.findall(r"^  ([A-Za-z0-9_-]+):[ \t]*$", body, re.M)
db_named = any(re.search(r"db|database|postgres|mysql|mongo", s, re.I) for s in services)
db_image = bool(re.search(r"image:[ \t]*[A-Za-z0-9._/-]*(postgres|mysql|mongo|mariadb)", body, re.I))
verdict = "DB-OK" if (db_named and db_image) else "DB-MISSING"
print("%s|%s" % (verdict, ",".join(services) or "-"))
PYDB
) || { echo "ac3 RED: the compose file could not be parsed - the database clause would be unproven"; exit 1; }
echo "ac3 evidence: compose database verdict / services listed = $DBSVC"
case "$DBSVC" in
  "none|"*) echo "ac3 RED: docker-compose.yml declares no services: block - the compose claim has nothing under it"; exit 1 ;;
  "DB-OK|"*) : ;;
  *) echo "ac3 RED: docker-compose.yml carries no database service on a real database image ($DBSVC) - the record may then claim only the honest sub-claim (app containerized, database NOT containerized), and a 2/2 that says 'full system incl. database' would be a false claim the map would have shipped"; exit 1 ;;
esac
printf "%s\n" "$S" | grep -qiE 'postgres|database service|db service' || { echo "ac3 RED: the record claims the database is containerized without naming the database service the compose file declares - name it (postgres:16-alpine) so the claim is checkable in 30 seconds"; exit 1; }
printf "%s\n" "$S" | grep -qiE "Local verification in five minutes" || { echo "ac3 RED: the record does not point at the README section that documents the compose path - that is where a grader finds the single command"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'docker compose up' || { echo "ac3 RED: the record never states the single compose command"; exit 1; }
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac3 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac3 GREEN: CONTAINERIZATION recorded - claim $1/$2, Dockerfile and docker-compose.yml both present and named, the database clause addressed, the single compose command locatable in the README path"
